#include<bits/stdc++.h>
using namespace std;
const int N = 2e3+10;
const int p = 1e9+7;
#define ll long long
ll c[N][N];
ll pw[N];
int n,m,k;
void init(){
    pw[0]=1;
    for(int i=0;i<N;i++){
        if(i)pw[i]=pw[i-1]*2%p;
        for(int j=0;j<=i;j++){
            if(j==0)c[i][j]=1;
            else c[i][j]=(c[i-1][j]+c[i-1][j-1])%p;
        }
    }
}
int main(){
    init();
    int t;
    cin>>t;
    while(t--){
        cin>>n>>m>>k;
        if(m<2*k||m-2*k>n-k){
            cout<<"0\n";
            continue;
        }
        ll ans=c[n][k]*c[n-k][m-2*k]%p;
        ans=ans*pw[m-2*k]%p;
        cout<<ans<<"\n";
    }
}

#include<bits/stdc++.h>
using namespace std;
const int N = 1e5+10;
vector<int> g[N];
int dep[N],vis[N],c[N];
int n,ans;
int dfs(int x,int fa){
    vis[x]=1;
    dep[x]=dep[fa]+1;
    int mx = dep[x];
    vector<int> tmp;
    tmp.push_back(mx);
    for(auto i:g[x]){
        if(i==fa||c[i]==c[x])continue;
        int d = dfs(i,x);
        tmp.push_back(d);
        mx = max(d,mx);
    }
    sort(tmp.begin(),tmp.end());
    int m = tmp.size(),res=1;
    if(m>1){
        res = tmp[m - 1] + tmp[m - 2] - 2 * dep[x] + 1;
    }
    ans=max(ans,res);
    return mx;
}
